mapper.update:
UPDATE attendance_records
SET status_code    = #{statusCode},
    failure_reason = #{failureReason}
WHERE attendance_id = #{attendanceId}

mapper.select:
SELECT COUNT(*) FROM attendance_records
WHERE student_id = #{studentId}
  AND class_id   = #{classId}
  AND attendance_date = #{attendanceDate}

mapper.update:
UPDATE attendance_records
status_code = #{statusCode}, failure_reason = #{failureReason}, checked_at = #{checkedAt}, check_out_at = #{checkOutAt},
WHERE attendance_id = #{attendanceId}

mapper.select:
SELECT * FROM attendance_records
WHERE student_id = #{studentId}
  AND class_id   = #{classId}
  AND attendance_date = #{attendanceDate}
LIMIT 1

mapper.update:
UPDATE attendance_records
SET check_out_at = #{checkOutAt},
    status_code  = #{statusCode}
WHERE attendance_id = #{attendanceId}

mapper.select:
SELECT start_time AS startTime, end_time AS endTime
FROM classes
WHERE class_id = #{classId}

SELECT e.student_id
FROM enrollments e
WHERE e.class_id = #{classId}
  AND e.status_code = 'ACTIVE'
  AND NOT EXISTS (
      SELECT 1 FROM attendance_records ar
      WHERE ar.student_id = e.student_id
        AND ar.class_id   = e.class_id
        AND ar.attendance_date = #{date}
  )

SELECT class_name
FROM classes
WHERE class_id = #{classId}

SELECT user_id
FROM users
WHERE login_id = #{loginId}
